//! Built-in SVG geometry extracted from the existing site.

use crate::model::Icon;
use maud::{Markup, html};

/// Render one icon with contextual sizing and an optional stylesheet class.
pub fn icon(kind: Icon, size: Option<u32>, class: Option<&str>) -> Markup {
    let filled = matches!(
        kind,
        Icon::Github | Icon::Twitter | Icon::Linkedin | Icon::Star
    );
    html! { svg viewBox="0 0 24 24" width=[size] height=[size] class=[class]
        fill=(if filled { "currentColor" } else { "none" })
        stroke=[(!filled).then_some("currentColor")] stroke-width=[(!filled).then_some("2")] {
        @match kind {
            Icon::Sun => { circle cx="12" cy="12" r="5" {  }line x1="12" y1="1" x2="12" y2="3" {  }line x1="12" y1="21" x2="12" y2="23" {  }line x1="4.22" y1="4.22" x2="5.64" y2="5.64" {  }line x1="18.36" y1="18.36" x2="19.78" y2="19.78" {  }line x1="1" y1="12" x2="3" y2="12" {  }line x1="21" y1="12" x2="23" y2="12" {  }line x1="4.22" y1="19.78" x2="5.64" y2="18.36" {  }line x1="18.36" y1="5.64" x2="19.78" y2="4.22" {  } }
            Icon::Moon => { path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" {  } }
            Icon::Menu => { line x1="3" y1="12" x2="21" y2="12" {  }line x1="3" y1="6" x2="21" y2="6" {  }line x1="3" y1="18" x2="21" y2="18" {  } }
            Icon::Location => { path d="M12 2a8 8 0 0 0-8 8c0 5.25 8 12 8 12s8-6.75 8-12a8 8 0 0 0-8-8z" {  }circle cx="12" cy="10" r="3" {  } }
            Icon::Arrow => { line x1="5" y1="12" x2="19" y2="12" {  }polyline points="12 5 19 12 12 19" {  } }
            Icon::Github => { path d="M12 0C5.37 0 0 5.37 0 12c0 5.31 3.435 9.795 8.205 11.385.6.105.825-.255.825-.57 0-.285-.015-1.23-.015-2.235-3.015.555-3.795-.735-4.035-1.41-.135-.345-.72-1.41-1.23-1.695-.42-.225-1.02-.78-.015-.795.945-.015 1.62.87 1.845 1.23 1.08 1.815 2.805 1.305 3.495.99.105-.78.42-1.305.765-1.605-2.67-.3-5.46-1.335-5.46-5.925 0-1.305.465-2.385 1.23-3.225-.12-.3-.54-1.53.12-3.18 0 0 1.005-.315 3.3 1.23.96-.27 1.98-.405 3-.405s2.04.135 3 .405c2.295-1.56 3.3-1.23 3.3-1.23.66 1.65.24 2.88.12 3.18.765.84 1.23 1.905 1.23 3.225 0 4.605-2.805 5.625-5.475 5.925.435.375.81 1.095.81 2.22 0 1.605-.015 2.895-.015 3.3 0 .315.225.69.825.57A12.02 12.02 0 0 0 24 12c0-6.63-5.37-12-12-12z" {  } }
            Icon::Star => { polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" {  } }
            Icon::Download => { path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" {  }polyline points="7 10 12 15 17 10" {  }line x1="12" y1="15" x2="12" y2="3" {  } }
            Icon::Calendar => { rect x="3" y="4" width="18" height="18" rx="2" ry="2" {  }line x1="16" y1="2" x2="16" y2="6" {  }line x1="8" y1="2" x2="8" y2="6" {  }line x1="3" y1="10" x2="21" y2="10" {  } }
            Icon::Edit => { path d="M12 20h9" {  }path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z" {  } }
            Icon::Twitter => { path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z" {  } }
            Icon::Linkedin => { path d="M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.761-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z" {  } }
        }
    } }
}
